import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */

import { add_or_delete_hloiday } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_location_details } from "@/mixins/GetLocations.js";
export default {
  mixins: [get_location_details],
  props: {
    addDialog: Boolean,
    actionType: String,
    rowInfo: Object
  },
  data() {
    return {
      loading: false,
      holidayName: "",
      date: "",
      checkholiday: null,
      showDatePicker: false,
      loaction: "",
      searchloc: "",
      loactionitems: []
    };
  },
  computed: {
    displayDate() {
      if (!this.date) return "";
      const date = new Date(this.date);
      const day = String(date.getDate()).padStart(2, "0");
      const month = String(date.getMonth() + 1).padStart(2, "0");
      const year = date.getFullYear();
      return `${day}-${month}-${year}`;
    }
  },
  watch: {
    addDialog: {
      async handler() {
        if (this.addDialog == true) {
          this.checkholiday = this.$store.getters.GetOrgDetails.organization.default_holiday_list == undefined ? true : this.$store.getters.GetOrgDetails.organization.default_holiday_list;
          if (this.actionType == "ADD") {
            await this.get_location_details();
            await this.fetch_details();
          }
        }
      },
      immediate: true
    }
  },
  methods: {
    formatDateToYYYYMMDD(dateString) {
      if (!dateString) return "";
      const date = new Date(dateString);
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, "0");
      const day = String(date.getDate()).padStart(2, "0");
      return `${year}-${month}-${day}`;
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.showDatePicker = false;
      this.date = "";
      this.holidayName = "";
      this.loaction = "";
      this.searchloc = "";
      this.loactionitems = [];
    },
    fetch_details() {
      if (this.locationList && Array.isArray(this.locationList)) {
        this.locationList.forEach(element => {
          this.loactionitems.push({
            location_name: element.location_name,
            location_id: element.location_id
          });
        });
      }
    },
    async validate_data() {
      if (this.actionType == "ADD") {
        const {
          valid
        } = await this.$refs.form?.validate?.();
        if (valid) {
          this.add_holiday_list();
        }
      } else if (this.actionType == "Delete") {
        this.add_holiday_list();
      }
    },
    async add_holiday_list() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      var inputParams = {};
      if (this.actionType == "ADD") {
        this.loaction = this.loaction == null ? "" : this.loaction;
        inputParams = {
          action_type: "ADD",
          holiday_date: this.formatDateToYYYYMMDD(this.date),
          holiday_name: this.holidayName,
          holiday_location: this.loaction.location_id == undefined ? "" : this.loaction.location_id,
          holiday_location_name: this.loaction.location_name == undefined ? "" : this.loaction.location_name,
          organization_id: data.organization.organization_id
        };
      } else {
        inputParams = {
          action_type: "DELETE",
          organization_id: data.organization.organization_id,
          holiday_id: this.rowInfo.holiday_id
        };
      }
      try {
        let result = await API.graphql(graphqlOperation(add_or_delete_hloiday, {
          input: inputParams
        }));
        this.loading = false;
        var response = JSON.parse(result.data.add_or_delete_hloiday);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          if (this.actionType == "ADD") {
            this.$refs.form?.reset();
          }
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
